import json
with open('after-cpm-packages.json') as f: data = json.load(f)
# Create baseline by reverting the two known changes
import copy
baseline = copy.deepcopy(data)
for proj in baseline.get('projects', []):
    path = proj['path']
    for fw in proj.get('frameworks', []):
        for pkg in fw.get('topLevelPackages', []):
            if 'Worker' in path and pkg['id'] == 'System.Text.Json':
                pkg['requestedVersion'] = '8.0.4'
                pkg['resolvedVersion'] = '8.0.4'
            if 'Shared' in path and pkg['id'] == 'Azure.Identity':
                pkg['requestedVersion'] = '1.11.4'
                pkg['resolvedVersion'] = '1.11.4'
with open('baseline-packages.json','w') as f: json.dump(baseline, f, indent=2)
print('baseline reconstructed')
